// throttle.ts
// Export function throttle(fn: () => void, maxPerWindow: number, windowMs: number):
// returns a wrapper that calls fn at most maxPerWindow times per windowMs and silently skips
// excess calls.

export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
    let calls = 0;
    const windowStart = 0;

    // We'll count calls within the window. For simplicity, we'll use a simple counter
    // that counts calls made within the last windowMs.
    // Since we don't have a global clock in the wrapper, we'll store the last call time.
    // But the problem says "silently skips excess calls" without needing complex state.
    // We'll implement a simple version that tracks calls in a closure.

    // Actually, let's implement it properly: track the time of the last N calls.
    // But the simplest approach that matches the requirement is:
    // We'll count how many times fn has been called in the current window.
    // We'll store the timestamp of each call.

    const timestamps = [];

    return () => {
        const now = Date.now();
        // Remove timestamps outside the window
        const windowStartMs = now - windowMs;
        timestamps = timestamps.filter(t => t >= windowStartMs);
        if (timestamps.length >= maxPerWindow) {
            // Skip this call silently
            return;
        }
        timestamps.push(now);
        fn();
    };
}

// Self-test
if (require.main === module) {
    const maxPerWindow = 5;
    const windowMs = 1000; // 1 second
    let callCount = 0;
    const fn = () => {
        callCount++;
    };

    const wrapper = throttle(fn, maxPerWindow, windowMs);

    // Make maxPerWindow + 1 calls quickly
    for (let i = 0; i < maxPerWindow + 1; i++) {
        wrapper();
    }

    // Should have called fn exactly maxPerWindow times
    if (callCount === maxPerWindow) {
        console.log('PASS: throttle correctly limited calls');
    } else {
        console.log(`FAIL: expected ${maxPerWindow} calls, got ${callCount}`);
        process.exit(1);
    }
}

